import kernelSinf = require( './index' );


// TESTS //

// The function returns a number...
{
	kernelSinf( 0.5, 0.2 ); // $ExpectType number
}

// The compiler throws an error if the function is provided values other than two numbers...
{
	kernelSinf( true, 3 ); // $ExpectError
	kernelSinf( false, 2 ); // $ExpectError
	kernelSinf( '5', 1 ); // $ExpectError
	kernelSinf( [], 1 ); // $ExpectError
	kernelSinf( {}, 2 ); // $ExpectError
	kernelSinf( ( x: number ): number => x, 2 ); // $ExpectError

	kernelSinf( 9, true ); // $ExpectError
	kernelSinf( 9, false ); // $ExpectError
	kernelSinf( 5, '5' ); // $ExpectError
	kernelSinf( 8, [] ); // $ExpectError
	kernelSinf( 9, {} ); // $ExpectError
	kernelSinf( 8, ( x: number ): number => x ); // $ExpectError

	kernelSinf( [], true ); // $ExpectError
	kernelSinf( {}, false ); // $ExpectError
	kernelSinf( false, '5' ); // $ExpectError
	kernelSinf( {}, [] ); // $ExpectError
	kernelSinf( '5', ( x: number ): number => x ); // $ExpectError
}

// The compiler throws an error if the function is provided insufficient arguments...
{
	kernelSinf(); // $ExpectError
	kernelSinf( 0 ); // $ExpectError
}
